module 	UART2(
	input  wire	     ipClk,
	input  wire		 ipReset,
	input  wire[7:0]ipTxData,
	input  wire		 ipTxSend,
	output reg 	     opTxBusy,
	output reg       opTx,
	input  wire      ipRx,
	output reg [7:0]opRxData,
	output reg		 opRxValid
);
reg [1:0]TxState;
reg [1:0]RxState;
reg [10:0]TxBdCount;
reg [10:0]RxBdCount;
assign opTxBusy = (TxState == Sending) ? 1'b1 : 1'b0;
assign opRxData = RxData;
assign opRxValid = (RxState == RxDone) ? 1'b1 : 1'b0;
always @(posedge ipClk) begin
	if (ipReset) begin
		TxState <= TxIdle;
		RxState <= RxIdle;
		TxBdCount <= 11'b0;
		RxBdCount <= 11'b0;
		opTxBusy <= 1'b0;
		opTx <= 1'b0;
		opRxData <= 8'b0;
		opRxValid <= 1'b0;
	end else begin
		case (TxState)
			TxIdle: begin
				if (ipTxSend) begin
					TxState <= Sending;
					opTx <= 1'b0;
					TxBdCount <= 11'b0;
				end
			end
			Sending: begin
				if (TxBdCount == 11'b11111111111) begin
					TxState <= TxDone;
					opTx <= 1'b1;
					TxBdCount <= 11'b0;
				end else begin
					opTx <= ipTxData[TxBdCount];
					TxBdCount <= TxBdCount + 1'b1;
				end
			end
			TxDone: begin
				TxState <= TxIdle;
				opTx <= 1'b0;
			end
			default: begin
				TxState <= TxIdle;
			end
		endcase
		case (RxState)
			RxIdle: begin
				if (ipRx == 1'b0) begin
					RxState <= Receiving;
					RxBdCount <= 11'b0;
					opRxData <= 8'b0;
				end
			end
			Receiving: begin
				if (RxBdCount == 11'b11111111111) begin
					RxState <= RxDone;
					opRxData <= opRxData << 1'b1;
					opRxData[0] <= ipRx;
					RxBdCount <= 11'b0;
					opRxValid <= 1'b1;
				end else begin
					opRxData <= opRxData << 1'b1;
					opRxData[0] <= ipRx;
					RxBdCount <= RxBdCount + 1'b1;
				end
			end
			RxDone: begin
				RxState <= RxIdle;
				opRxData <= 8'b0;
				opRxValid <= 1'b0;
			end
			default: begin
				RxState <= RxIdle;
			end
		endcase
	end
end
endmodule

