module vga_ctrl(
input wire pixel_clk,
output wire hsync,
output wire vsync,
output wire [9:0] pixel_x,
output wire [9:0] pixel_y,
output wire visible_region
); 

parameter [31:0] total_pixels=640;
parameter [31:0] hsync_pulse=96;
parameter [31:0] hsync_blank=48;
parameter [31:0] vsync_pulse=2;
parameter [31:0] vsync_blank=31;
parameter [31:0] hsync_start=640;
parameter [31:0] hsync_end=752;
parameter [31:0] vsync_start=480;
parameter [31:0] vsync_end=525;
reg [31:0] hcount;
reg [31:0] vcount;
wire [31:0] hcount_max = total_pixels - hsync_start - hsync_end;
wire [31:0] vcount_max = total_pixels - vsync_start - vsync_end;
  always @(posedge pixel_clk) begin
    if((hcount == hcount_max)) begin
      hcount <= 0;
    end
    else begin
      hcount <= hcount + 1;
    end
  end
  always @(posedge pixel_clk) begin
    if((vcount == vcount_max)) begin
      vcount <= 0;
    end
    else begin
      vcount <= vcount + 1;
    end
  end
  assign hsync = (hcount >= hsync_start && hcount < hsync_end) ? 1'b1 : 1'b0;
  assign vsync = (vcount >= vsync_start && vcount < vsync_end) ? 1'b1 : 1'b0;
  assign pixel_x = hcount - hsync_start;
  assign pixel_y = vcount - vsync_start;
  assign visible_region = (pixel_x >= 0 && pixel_x < 640 && pixel_y >= 0 && pixel_y < 480) ? 1'b1 : 1'b0;
endmodule

