module toe_s_axis_listen_port_req_reg_slice
#(parameter
    N = 8   
) (

    input  wire         clk,
    input  wire         reset,

    input  wire [N-1:0] s_data,
    input  wire         s_valid,
    output wire         s_ready,

    output wire [N-1:0] m_data,
    output wire         m_valid,
    input  wire         m_ready
);
localparam DATA_WIDTH = N;
    localparam STAGES = 2;
    localparam ZERO = 0;
    localparam ONE = 1;
    localparam TWO = 2;

    reg [DATA_WIDTH-1:0] data_p1;
    reg [DATA_WIDTH-1:0] data_p2;
    reg [1:0]            state;
    reg            s_ready_int;
    reg            m_valid_int;

    assign s_ready = s_ready_int;
    assign m_data = data_p1;
    assign m_valid = m_valid_int;

    always @(posedge clk) begin
        if (reset) begin
            data_p1 <= {DATA_WIDTH{1'b0}};
            data_p2 <= {DATA_WIDTH{1'b0}};
            state <= ZERO;
            s_ready_int <= 1'b0;
            m_valid_int <= 1'b0;
        end else begin
            s_ready_int <= s_ready;
            m_valid_int <= m_valid;
            if (state == ZERO) begin
                if (s_valid & s_ready) begin
                    data_p1 <= s_data;
                    data_p2 <= s_data;
                    state <= ONE;
                end
            end else if (state == ONE) begin
                if (s_valid & s_ready) begin
                    data_p1 <= s_data;
                    state <= TWO;
                end else if (m_ready) begin
                    data_p2 <= data_p1;
                    state <= ZERO;
                end
            end else if (state == TWO) begin
                if (s_valid & s_ready) begin
                    data_p1 <= s_data;
                    state <= ZERO;
                end
            end
        end
    end

endmodule

