module AXI_WRITE_DATA_CHANNEL_model(
input wire clk,
input wire resetn,
input wire [31:0] data,
input wire go,
output reg done,
output wire [31:0] WDATA,
output reg [3:0] WSTRB,
output reg WVALID,
input wire WREADY
); 

parameter [31:0] IDLE=4'd0;
parameter [31:0] RUNNING=4'd1;
parameter [31:0] COMPLETE=4'd2;
parameter [31:0] RESET=4'd3;
reg [31:0] current_state;
reg [31:0] next_state;
  always @(posedge clk, posedge resetn) begin
    if((resetn == 1'b0)) begin
      current_state <= RESET;
    end else begin
      current_state <= next_state;
    end
  end
  always @(current_state, go, WREADY) begin
    case(current_state)
    RESET : begin
      next_state <= IDLE;
    end
    IDLE : begin
      if((go == 1'b1)) begin
        next_state <= RUNNING;
      end
      else begin
        next_state <= IDLE;
      end
    end
    RUNNING : begin
      if((WREADY == 1'b1)) begin
        next_state <= COMPLETE;
      end
      else begin
        next_state <= RUNNING;
      end
    end
    COMPLETE : begin
      next_state <= IDLE;
    end
    default : begin
      next_state <= IDLE;
    end
    endcase
  end
  always @(current_state, go, WREADY) begin
    case(current_state)
    RESET : begin
      done <= 1'b0;
      WDATA <= {32{1'b0}};
      WSTRB <= {4{1'b0}};
      WVALID <= 1'b0;
    end
    IDLE : begin
      done <= 1'b0;
      WDATA <= {32{1'b0}};
      WSTRB <= {4{1'b0}};
      WVALID <= 1'b0;
    end
    RUNNING : begin
      done <= 1'b0;
      WDATA <= data;
      WSTRB <= {4{1'b1}};
      WVALID <= 1'b1;
    end
    COMPLETE : begin
      done <= 1'b1;
      WDATA <= {32{1'b0}};
      WSTRB <= {4{1'b0}};
      WVALID <= 1'b0;
    end
    default : begin
      done <= 1'b0;
      WDATA <= {32{1'b0}};
      WSTRB <= {4{1'b0}};
      WVALID <= 1'b0;
    end
    endcase
  end
endmodule

