module fifo36_demux
  #(parameter match_data = 0,
    parameter match_mask = 0)
   (input clk, input reset, input clear,
    input [35:0] data_i, input src_rdy_i, output dst_rdy_o,
    output [35:0] data0_o, output src0_rdy_o, input dst0_rdy_i,
    output [35:0] data1_o, output src1_rdy_o, input dst1_rdy_i);
localparam IDLE = 0;
   localparam DATA0 = 1;
   localparam DATA1 = 2;
   reg [1:0] state;
   reg src0_rdy, src1_rdy;
   reg [35:0] data0, data1;
   always @(posedge clk) begin
      if (reset) begin
         state <= IDLE;
         src0_rdy <= 0;
         src1_rdy <= 0;
         data0 <= 0;
         data1 <= 0;
      end else if (clear) begin
         state <= IDLE;
         src0_rdy <= 0;
         src1_rdy <= 0;
         data0 <= 0;
         data1 <= 0;
      end else begin
         case (state)
            IDLE: begin
               if (src_rdy_i && dst0_rdy_i) begin
                  state <= DATA0;
                  src0_rdy <= 1;
                  src1_rdy <= 0;
                  data0 <= data_i;
                  data1 <= 0;
               end else if (src_rdy_i && dst1_rdy_i) begin
                  state <= DATA1;
                  src0_rdy <= 0;
                  src1_rdy <= 1;
                  data0 <= 0;
                  data1 <= data_i;
               end
            end
            DATA0: begin
               if (dst0_rdy_i) begin
                  state <= IDLE;
                  src0_rdy <= 0;
                  src1_rdy <= 0;
                  data0 <= data_i;
                  data1 <= 0;
               end
            end
            DATA1: begin
               if (dst1_rdy_i) begin
                  state <= IDLE;
                  src0_rdy <= 0;
                  src1_rdy <= 0;
                  data0 <= 0;
                  data1 <= data_i;
               end
            end
         endcase
      end
   end
   assign dst_rdy_o = (state == DATA0) || (state == DATA1);
   assign data0_o = (state == DATA0) ? data_i : data0;
   assign data1_o = (state == DATA1) ? data_i : data1;
   assign src0_rdy_o = src0_rdy;
   assign src1_rdy_o = src1_rdy;
