module branch_ctrl(
	input [31:0]	data_rs1	,
	input [31:0]	data_rs2	,
	input [2:0]		funct3		,
	output	reg		jmpb
);
always @(*) begin
		case (funct3)
			4'b000: jmpb = (data_rs1 == data_rs2);
			4'b001: jmpb = (data_rs1 != data_rs2);
			4'b010: jmpb = (data_rs1 < data_rs2);
			4'b011: jmpb = (data_rs1 > data_rs2);
			4'b100: jmpb = (data_rs1 < $signed(data_rs2));
