module jtframe_romrq #(parameter AW=18, DW=8 )(
    input               rst,
    input               clk,
    input               clr, 
    input [21:0]        offset,
    input [AW-1:0]      addr,
    input               addr_ok,    
    input [31:0]        din,
    input               din_ok,
    input               we,
    output reg          req,
    output reg          data_ok,    
    output     [21:0]   sdram_addr,
    output reg [DW-1:0] dout
);
reg [AW+DW-1:0] addr_req;
reg [AW+DW-1:0] cached_addr0;
reg [AW+DW-1:0] cached_addr1;
reg [DW-1:0]    cached_data0;
reg [DW-1:0]    cached_data1;
reg [AW+DW-1:0] subaddr;
reg             good;
always @(posedge clk or posedge rst) begin
    if (rst) begin
        addr_req <= 0;
        cached_addr0 <= 0;
        cached_addr1 <= 0;
        cached_data0 <= 0;
        cached_data1 <= 0;
        subaddr <= 0;
        good <= 0;
    end else begin
        if (clr) begin
            addr_req <= 0;
            cached_addr0 <= 0;
            cached_addr1 <= 0;
            cached_data0 <= 0;
            cached_data1 <= 0;
            subaddr <= 0;
            good <= 0;
        end else begin
            if (addr_ok) begin
                addr_req <= {addr, {DW{1'b0}}};
                if (addr_req[AW+DW-1:AW] == 0) begin
                    cached_addr0 <= addr_req;
                    cached_data0 <= din;
                    good <= 1;
                end else if (addr_req[AW+DW-1:AW] == 1) begin
                    cached_addr1 <= addr_req;
                    cached_data1 <= din;
                    good <= 1;
                end
            end
            if (we) begin
                if (addr_req[AW+DW-1:AW] == 0) begin
                    cached_data0 <= din;
                    good <= 1;
                end else if (addr_req[AW+DW-1:AW] == 1) begin
                    cached_data1 <= din;
                    good <= 1;
                end
            end
            if (addr_req[AW+DW-1:AW] == 0) begin
                subaddr <= addr_req[AW+DW-1:AW+DW-1];
            end else if (addr_req[AW+DW-1:AW] == 1) begin
                subaddr <= addr_req[AW+DW-1:AW+DW-1];
            end
        end
    end
end
assign req = (addr_req[AW+DW-1:AW] == 0) ? 1'b0 : 1'b1;
assign sdram_addr = addr_req[AW+DW-1:AW] == 0 ? addr_req[AW+DW-1:AW+DW-1] : addr_req[AW+DW-1:AW+DW-1] + offset;
assign data_ok = (addr_req[AW+DW-1:AW] == 0) ? good : 1'b0;
assign dout = (subaddr == 0) ? cached_data0 : cached_data1;
endmodule

