module CW_REGISTER(
input wire [2:0] D,
input wire [2:0] A,
input wire WR,
input wire RD,
input wire CLK,
input wire RST,
output wire WCTRL,
output reg [6:0] Y
); 

reg [6:0] data;
reg [6:0] next_data;
reg [2:0] next_A;
reg [2:0] next_WR;
reg [2:0] next_RD;
reg [2:0] next_CLK;
reg [2:0] next_RST;
  always @(posedge CLK, posedge RST) begin
    if((RST == 1'b1)) begin
      data <= {7{1'b0}};
      next_data <= {7{1'b0}};
    end else begin
      data <= next_data;
      next_data <= {7{1'b0}};
    end
  end
  always @(posedge CLK, posedge RST) begin
    if((RST == 1'b1)) begin
      next_data <= {7{1'b0}};
    end else begin
      next_data <= data;
    end
  end
  always @(posedge CLK, posedge RST) begin
    if((RST == 1'b1)) begin
      next_A <= {3{1'b0}};
    end else begin
      next_A <= A;
    end
  end
  always @(posedge CLK, posedge RST) begin
    if((RST == 1'b1)) begin
      next_WR <= {3{1'b0}};
    end else begin
      next_WR <= WR;
    end
  end
  always @(posedge CLK, posedge RST) begin
    if((RST == 1'b1)) begin
      next_RD <= {3{1'b0}};
    end else begin
      next_RD <= RD;
    end
  end
  always @(posedge CLK, posedge RST) begin
    if((RST == 1'b1)) begin
      next_CLK <= {3{1'b0}};
    end else begin
      next_CLK <= CLK;
    end
  end
  always @(posedge CLK, posedge RST) begin
    if((RST == 1'b1)) begin
      next_RST <= {3{1'b0}};
    end else begin
      next_RST <= RST;
    end
  end
  always @(next_A, next_WR, next_RD, next_CLK, next_RST) begin
    if((next_RST == 1'b1)) begin
      Y <= {7{1'b0}};
    end else begin
      if((next_WR == 1'b1)) begin
        if((next_RD == 1'b1)) begin
          if((next_A == 3'b000)) begin
            Y <= {7{1'b1}};
          end
          else if((next_A == 3'b001)) begin
            Y <= {6{1'b0}, 1'b1};
          end
          else if((next_A == 3'b010)) begin
            Y <= {5{1'b0}, 2'b11};
          end
          else if((next_A == 3'b011)) begin
            Y <= {4{1'b0}, 3'b111};
          end
          else if((next_A == 3'b100)) begin
            Y <= {3{1'b0}, 4'b1111};
          end
          else if((next_A == 3'b101)) begin
            Y <= {2{1'b0}, 5'b11111};
          end
          else if((next_A == 3'b110)) begin
            Y <= {1{1'b0}, 6'b111111};
          end
          else begin
            Y <= {7{1'b0}};
          end
        end
        else begin
          Y <= {7{1'b0}};
        end
      end
      else begin
        Y <= {7{1'b0}};
      end
    end
  end
endmodule

