module parallel_if();
reg [3:0] counter;
    reg reset, enable, up_en, down_en;
    always @(posedge clk) begin
        if (reset) begin
            counter <= 0;
        end else begin
            if (enable) begin
                if (up_en) begin
                    counter <= counter + 1;
                end else if (down_en) begin
                    counter <= counter - 1;
                end
            end
        end
    end
endmodule

module address_comp(
input wire [3:0] addr_sel,
input wire [7:0] serial_in,
output wire [2:0] mode_data,
output wire addr_valid,
output wire sdprev_disable,
output wire vsync_cmd,
input wire byte_rcvd
); 

wire parity;
wire [3:0] addr;
  assign parity = serial_in[7] ^ serial_in[6] ^ serial_in[5] ^ serial_in[4];
  assign addr = serial_in[3:0];
  assign mode_data = serial_in[7:5];
  assign addr_valid = byte_rcvd & (addr == addr_sel) & parity;
  assign sdprev_disable = addr_sel == 4'b0000 ? 1'b1 : 1'b0;
  assign vsync_cmd = serial_in[7] & serial_in[6] & serial_in[5] & serial_in[4];
endmodule

module fftFramePulseGen(
input wire [7:0] counterValue,
output wire framePulse
); 

