    always @(posedge i_clock or negedge reset) begin
        if (reset) begin
            scan_code <= 8'b0;
            counter <= 4'b0;
        end else begin
            if (counter == 4'b1111) begin
                scan_code <= {scan_code[6:0], i_data};
