module dhcp_client_m_axis_open_port_fifo
#(parameter
    DATA_BITS  = 8,
    DEPTH_BITS = 4
)(
    input  wire                 clk,
    input  wire                 aclr,
    output wire                 empty_n,
    output wire                 full_n,
    input  wire                 read,
    input  wire                 write,
    output wire [DATA_BITS-1:0] dout,
    input  wire [DATA_BITS-1:0] din
);
localparam DEPTH = 1 << DEPTH_BITS;

reg [DATA_BITS-1:0] mem [0:DEPTH-1];
reg [DEPTH_BITS-1:0] index;
reg empty_n_tmp;
reg full_n_tmp;

assign dout = mem[index];
assign empty_n = empty_n_tmp;
assign full_n  = full_n_tmp;

always @(posedge clk) begin
    if (aclr) begin
        empty_n_tmp <= 1'b1;
        full_n_tmp  <= 1'b0;
        index       <= 0;
    end else begin
        if (write) begin
            mem[index] <= din;
            if (index == DEPTH-1)
                full_n_tmp <= 1'b1;
            else
                full_n_tmp <= 1'b0;
            if (read)
                index <= index - 1;
            else
                index <= index + 1;
        end
        if (read) begin
            if (index == 0)
                empty_n_tmp <= 1'b1;
            else
                empty_n_tmp <= 1'b0;
            if (index == DEPTH-1)
                full_n_tmp  <= 1'b0;
            else
                full_n_tmp  <= 1'b1;
        end
    end
end

endmodule

