module synchronize(
    input clk,
    input async_in,
    input reset,
    output reg sync_out
    );
reg sync_in;
    reg sync_in2;
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            sync_in <= 0;
            sync_in2 <= 0;
        end else begin
            sync_in <= async_in;
            sync_in2 <= sync_in;
        end
    end
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            sync_out <= 0;
        end else begin
            sync_out <= sync_in2;
        end
    end
endmodule

module pipelined_multiplier (a, b, clk, pdt);
input [size-1 : 0] a;
input [size-1 : 0] b;
input clk;
output [2*size-1 : 0] pdt;
parameter size = 16;
parameter level = 10;
reg [size-1 : 0] a_int;
reg [size-1 : 0] b_int;
reg [2*size-1 : 0] pdt_int [level-1 : 0];
reg [2*size-1 : 0] pdt;
always @(posedge clk) begin
    a_int <= a;
    b_int <= b;
    pdt_int[0] <= a_int * b_int;
    for (int i = 0; i < level-1; i = i+1) begin
        pdt_int[i+1] <= pdt_int[i] * a_int * b_int;
    end
    pdt <= pdt_int[level-1];
end
endmodule

