module mux31_5b(
input wire [4:0] E0,
input wire [4:0] E1,
input wire [4:0] E2,
input wire [1:0] Sel,
output reg [4:0] S
); 

always @(E0, E1, E2, Sel) begin
    case(Sel)
    2'b00 : S <= E0;
    2'b01 : S <= E1;
    2'b10 : S <= E2;
    default : S <= 5'b00000;
    endcase
  end
endmodule

