module scan_hex_led_disp(
    input clk,reset,
    input [3:0] hex3,hex2,hex1,hex0,
    input [3:0] dp,
    output reg[3:0] en, 
    output reg[7:0] sseg
    );
reg [3:0] cnt;
    always @(posedge clk or posedge reset) begin
        if(reset) cnt <= 0;
        else if(cnt == 3'd15) cnt <= 0;
        else cnt <= cnt + 1;
    end
    always @(posedge clk or posedge reset) begin
        if(reset) en <= 0;
        else if(cnt == 0) en <= 1;
        else if(cnt == 1) en <= 2;
        else if(cnt == 2) en <= 4;
        else if(cnt == 3) en <= 8;
        else if(cnt == 4) en <= 16;
        else if(cnt == 5) en <= 32;
        else if(cnt == 6) en <= 64;
        else if(cnt == 7) en <= 128;
        else if(cnt == 8) en <= 256;
        else if(cnt == 9) en <= 512;
        else if(cnt == 10) en <= 1024;
        else if(cnt == 11) en <= 2048;
        else if(cnt == 12) en <= 4096;
        else if(cnt == 13) en <= 8192;
        else if(cnt == 14) en <= 16384;
        else if(cnt == 15) en <= 32768;
    end
    always @(posedge clk or posedge reset) begin
        if(reset) sseg <= 0;
        else case(cnt)
            0: sseg <= 16'h3f;
            1: sseg <= 16'h06;
            2: sseg <= 16'h5b;
            3: sseg <= 16'h4f;
            4: sseg <= 16'h66;
            5: sseg <= 16'h6d;
            6: sseg <= 16'h7d;
            7: sseg <= 16'h07;
            8: sseg <= 16'h7f;
            9: sseg <= 16'h6f;
            10: sseg <= 16'h77;
            11: sseg <= 16'h7c;
            12: sseg <= 16'h39;
            13: sseg <= 16'h5e;
            14: sseg <= 16'h79;
            15: sseg <= 16'h71;
        endcase
    end
    always @(posedge clk or posedge reset) begin
        if(reset) sseg[7] <= 0;
        else sseg[7] <= dp[cnt];
    end
endmodule

