module binary_updown_counter #(parameter BITS = 1)
        (input wire clk, input wire rst, input wire ena,
         input wire updown, output wire [BITS - 1:0] out, output wire ovf);
reg [BITS - 1:0] cnt;
    wire [BITS - 1:0] enable_wires;
    assign enable_wires = {enable_wires[BITS - 2:0], ena};
    always @(posedge clk, posedge rst) begin
        if (rst) begin
            cnt <= 0;
        end else begin
            if (enable_wires[BITS - 1]) begin
                if (updown) begin
                    if (cnt == 2 ** BITS - 1) begin
                        cnt <= 0;
                    end else begin
                        cnt <= cnt + 1;
                    end
                end else begin
                    if (cnt == 0) begin
                        cnt <= 2 ** BITS - 1;
                    end else begin
                        cnt <= cnt - 1;
                    end
                end
            end
        end
    end
    assign out = cnt;
    assign ovf = (cnt == 2 ** BITS - 1) ^ (cnt == 0);
endmodule

