module syn_gen
(
    input              I_pxl_clk   ,
    input              I_rst_n     ,
    input      [15:0]  I_h_total   ,
    input      [15:0]  I_h_sync    ,
    input      [15:0]  I_h_bporch  ,
    input      [15:0]  I_h_res     ,
    input      [15:0]  I_v_total   ,
    input      [15:0]  I_v_sync    ,
    input      [15:0]  I_v_bporch  ,
    input      [15:0]  I_v_res     ,
    input      [15:0]  I_rd_hres   ,
    input      [15:0]  I_rd_vres   ,
    input              I_hs_pol    ,
    input              I_vs_pol    ,
    output reg         O_rden      ,
    output reg         O_de        ,   
    output reg         O_hs        ,
    output reg         O_vs         
);
reg [15:0] V_cnt;
    reg [15:0] H_cnt;
    wire [15:0] Pout_de_w;
    wire [15:0] Pout_hs_w;
    wire [15:0] Pout_vs_w;
    wire [15:0] Rden_w;
    assign Pout_de_w = (V_cnt < I_v_total) & (H_cnt < I_h_total);
    assign Pout_hs_w = (V_cnt < I_v_total) & (H_cnt < I_h_total) & (H_cnt >= I_h_sync) & (H_cnt < (I_h_sync + I_h_res));
    assign Pout_vs_w = (V_cnt < I_v_total) & (H_cnt < I_h_total) & (V_cnt >= I_v_sync) & (V_cnt < (I_v_sync + I_v_res));
    assign Rden_w = (V_cnt < I_v_total) & (H_cnt < I_h_total) & (V_cnt >= I_v_sync) & (V_cnt < (I_v_sync + I_v_res)) & (H_cnt >= I_h_sync) & (H_cnt < (I_h_sync + I_h_res));
    assign O_rden = Rden_w;
    assign O_de = Pout_de_w;
    assign O_hs = Pout_hs_w;
    assign O_vs = Pout_vs_w;
    always @(posedge I_pxl_clk or negedge I_rst_n)
    begin
        if (!I_rst_n)
        begin
            V_cnt <= 0;
            H_cnt <= 0;
        end
        else
        begin
            V_cnt <= (V_cnt == I_v_total - 1) ? 0 : V_cnt + 1;
            H_cnt <= (H_cnt == I_h_total - 1) ? 0 : H_cnt + 1;
        end
    end
endmodule

module alu
    #(parameter WIDTH = 32)
    (   input  [WIDTH - 1 : 0] a,b,
        input  [2 : 0] m,
        output reg [WIDTH - 1 : 0] y,
        output reg zf,      
        output reg cf,      
        output reg of      
    );
always @* begin
        case (m)
            3'b000: y = a + b;
            3'b001: y = a - b;
            3'b010: y = a & b;
            3'b011: y = a | b;
            3'b100: y = a ^ b;
            3'b101: y = a - b;
            3'b110: y = a + b;
            3'b111: y = a - b;
        endcase
        cf = y[WIDTH - 1];
        zf = (y == 0);
        of = (a[WIDTH - 1] ^ b[WIDTH - 1] ^ y[WIDTH - 1]) & cf;
    end
endmodule

