module pddm (
	input sdi, 
	input signed_data, 
	output [31:0] dout, 
	input ock, uck, 
	input rstn, clk
);
reg [31:0] sigma, undersampled_sigma;
	reg delta, deriv;

	always @(posedge clk or negedge rstn) begin
		if (!rstn) begin
			sigma <= 0;
			undersampled_sigma <= 0;
			delta <= 0;
			deriv <= 0;
		end else begin
			if (ock) begin
				if (sdi) begin
					sigma <= sigma + 1;
					undersampled_sigma <= undersampled_sigma + 1;
				end else begin
					sigma <= sigma - 1;
					undersampled_sigma <= undersampled_sigma - 1;
				end
			end
			if (uck) begin
				if (sdi) begin
					delta <= 1;
					deriv <= 1;
				end else begin
					delta <= -1;
					deriv <= -1;
				end
			end
		end
	end

	assign dout = (signed_data) ? {delta, undersampled_sigma - sigma} : {delta, undersampled_sigma - sigma};
endmodule

