module ff_d_nand(
    output reg Q,
    input D, CLK, CLR_BAR   
);
parameter Vcc = 1.2;
    parameter C_L = 0.000000001;
    parameter t_hmin = 0.0;
    parameter t_hmax = 0.0;
    integer counter = 0;
    always @(posedge CLK) begin
        if (CLR_BAR) begin
            Q <= 0;
        end else begin
            Q <= D;
        end
    end
    always @(posedge CLK) begin
        if (CLR_BAR) begin
            counter <= 0;
        end else begin
            counter <= counter + 1;
        end
    end
    always @(posedge CLK) begin
        if (CLR_BAR) begin
            $display("Power dissipation: %d", counter * C_L * Vcc^2);
        end
    end
endmodule

