module timer_stream_adapter_synchTime_2_fifo
#(parameter
    DATA_BITS  = 8,
    DEPTH_BITS = 4
)(
    input  wire                 clk,
    input  wire                 aclr,
    output wire                 empty_n,
    output wire                 full_n,
    input  wire                 read,
    input  wire                 write,
    output wire [DATA_BITS-1:0] dout,
    input  wire [DATA_BITS-1:0] din
);
localparam DEPTH = 1 << DEPTH_BITS;

reg [DATA_BITS-1:0] mem [0:DEPTH-1];
reg                 empty_n, full_n, read, write;
reg                 index;

assign dout = mem[index];
assign empty_n = full_n & ~write;
assign full_n = empty_n & ~read;

always @(posedge clk) begin
    if (aclr) begin
        empty_n <= 1'b1;
        full_n  <= 1'b0;
        index  <= 0;
        read   <= 1'b0;
        write  <= 1'b0;
    end else begin
        if (write) begin
            mem[index] <= din;
            if (index == DEPTH-1)
                index <= 0;
            else
                index <= index + 1;
            write <= 1'b0;
        end
        if (read) begin
            if (index == 0)
                index <= DEPTH-1;
            else
                index <= index - 1;
            read <= 1'b0;
        end
    end
end

endmodule

module debounce(
input clk,
input btn_input,
output reg btn_output
);
reg [31:0] timer;
reg pre;
always @(posedge clk) begin
    if (timer == 1000000) begin
        if (btn_input == pre) begin
            btn_output <= btn_input;
            timer <= 0;
            pre <= btn_input;
        end
    end else begin
        timer <= timer + 1;
    end
end
endmodule

