module gray_Nbits (clk, reset, enable, gray_out);

input wire clk, reset, enable;
output wire [N-1:0]gray_out;
parameter N = 4;
parameter SIZE = N+1;
reg [SIZE-1:0]state = Zeros;
reg [SIZE-1:0]toggle = Zeros;
reg [SIZE-1:0]state_next = Zeros;
assign gray_out = state[SIZE-2:0];
always @(posedge clk or posedge reset) begin
	if (reset) begin
		state <= Zeros;
	end else begin
		if (enable) begin
			state <= state_next;
		end
	end
end
always @(state) begin
	toggle[0] = 1;
	for (int i = 1; i < SIZE; i = i + 1) begin
		toggle[i] = (state[i-1] ^ state[i]) & toggle[i-1];
	end
end
always @(state) begin
	state_next[0] = 0;
	for (int i = 1; i < SIZE; i = i + 1) begin
		state_next[i] = (toggle[i-1] ^ state[i-1]) ^ state[i];
	end
end
endmodule

