module MEM_BLK_V5_0( clk,
                     write_en,
                     read_en,
                     wr_addr,
                     rd_addr,
                     data_in,
                     data_out,
                     rst
                   );


input                    clk;       
input                    write_en;    
input                    read_en ;
input  [(addr_value-1):0]  wr_addr;   
input  [(addr_value-1):0]  rd_addr;   
input  [(data_width-1):0]   data_in;   
input                    rst ;

output [(data_width-1):0]   data_out;
parameter data_width = 16;
parameter addr_value = 16;

reg  [(data_width-1):0]  mem [0:addr_value-1];
reg  [(data_width-1):0]  data_out;

always @(posedge clk)
begin
    if (rst == 1'b1)
    begin
        data_out <= {((data_width-1)-(0)+1){1'b0}};
    end
    else
    begin
        if (write_en == 1'b1)
        begin
            mem[wr_addr] <= data_in;
        end
        else
        begin
            data_out <= mem[rd_addr];
        end
    end
end

endmodule

