module data_deal(
	clk,
	rst_n,
	data_in,
	data_in_sign,

	data_out,
	data_out_sign,
	data_valid,
	data_ok
    );



	input 	clk;
	input 	rst_n;
	input 	[6:0]	data_in;
	input 	data_in_sign;

	output	[6:0]	data_out;
	output	data_out_sign;
	input 	data_valid;
	output	data_ok;
reg 	[6:0]	data_reg;
	reg 	data_regnum;
	reg 	data_out_sign;
	reg 	data_ok;

	always @(posedge clk or negedge rst_n) begin
		if (!rst_n) begin
			data_reg <= 7'b0;
			data_regnum <= 1'b0;
			data_out_sign <= 1'b0;
			data_ok <= 1'b0;
		end else begin
			if (data_valid) begin
				if (data_in_sign) begin
					data_reg <= data_reg + data_in;
					data_regnum <= data_regnum + 1'b1;
				end else begin
					data_reg <= data_reg - data_in;
					data_regnum <= data_regnum + 1'b1;
				end
				if (data_regnum == 8) begin
					if (data_reg == 7'b14 || data_reg == 7'b24) begin
						data_ok <= 1'b1;
					end else begin
						data_ok <= 1'b0;
					end
				end
			end else begin
				data_reg <= 7'b0;
				data_regnum <= 1'b0;
				data_out_sign <= 1'b0;
				data_ok <= 1'b0;
			end
			if (data_valid) begin
				data_out_sign <= 1'b1;
			end else begin
				data_out_sign <= 1'b0;
			end
			if (data_out_sign) begin
				data_out <= data_reg;
			end else begin
				data_out <= 7'b0;
			end
		end
	end
endmodule

