module toe_m_axis_rx_data_rsp_metadata_reg_slice
#(parameter
    N = 8   
) (

    input  wire         clk,
    input  wire         reset,

    input  wire [N-1:0] s_data,
    input  wire         s_valid,
    output wire         s_ready,

    output wire [N-1:0] m_data,
    output wire         m_valid,
    input  wire         m_ready
);
localparam
    ZERO = 3'b000,
    ONE  = 3'b001,
    TWO  = 3'b010;

reg [N-1:0] data_p1;
reg [N-1:0] data_p2;
reg [2:0] current_state;
reg [2:0] next_state;

assign m_data = data_p1;
assign m_valid = (current_state == TWO && m_ready);
assign s_ready = (current_state == ZERO || current_state == ONE);

always @(posedge clk) begin
    if (reset) begin
        data_p1 <= {N{1'b0}};
        data_p2 <= {N{1'b0}};
        current_state <= ZERO;
    end else begin
        data_p1 <= data_p2;
        data_p2 <= s_data;
        current_state <= next_state;
    end
end

always @(posedge clk) begin
    if (reset) begin
        next_state <= ZERO;
    end else begin
        case (current_state)
            ZERO : if (s_valid & s_ready) next_state <= ONE;
                    else next_state <= ZERO;
            ONE  : if (s_valid & s_ready) next_state <= TWO;
                    else next_state <= ONE;
            TWO  : if (m_valid & m_ready) next_state <= ZERO;
                    else next_state <= TWO;
            default : next_state <= ZERO;
        endcase
    end
end

endmodule

module Incer #(
    parameter DATA_WIDTH = 8
)
(clk,arstn,din,dout,mode);

