module AXIS_WB_WB_Queue( 
  input         clock, 
  input         reset, 
  output        io_enq_ready, 
  input         io_enq_valid, 
  input  [31:0] io_enq_bits, 
  input         io_deq_ready, 
  output        io_deq_valid, 
  output [31:0] io_deq_bits 
);
localparam DEPTH = 512;
  reg [31:0] ram [0:DEPTH-1];
  reg [31:0] value, value_1;
  reg maybe_full;
  assign io_enq_ready = 1'b1;
  assign io_deq_valid = 1'b1;
  always @(posedge clock) begin
    if (reset) begin
      value <= 0;
      value_1 <= 0;
      maybe_full <= 0;
    end else if (io_enq_valid) begin
      if (maybe_full) begin
        value <= value_1;
      end
      ram[value] <= io_enq_bits;
      value <= value + 1;
      if (value == DEPTH - 1) begin
        maybe_full <= 1;
      end
    end else if (io_deq_ready) begin
      value_1 <= value;
      if (value == 0) begin
        maybe_full <= 0;
      end
    end
  end
  assign io_deq_bits = ram[value_1];
endmodule

