		if (start) begin
			state <= 3'b000;
		end else if (state[2] == 0 && state[1] == 0 && state[0] == 0) begin
			state <= 3'b001;
		end else if (state[2] == 0 && state[1] == 0 && state[0] == 1) begin
			state <= 3'b010;
		end else if (state[2] == 0 && state[1] == 1 && state[0] == 0) begin
			state <= 3'b011;
		end else if (state[2] == 0 && state[1] == 1 && state[0] == 1) begin
			state <= 3'b100;
		end else if (state[2] == 1 && state[1] == 0 && state[0] == 0) begin
			state <= 3'b101;
		end else if (state[2] == 1 && state[1] == 0 && state[0] == 1) begin
			state <= 3'b110;
		end else if (state[2] == 1 && state[1] == 1 && state[0] == 0) begin
			state <= 3'b111;
		end else begin
			state <= state;
		end
	end
endmodule

