module sparc_ifu_esl_lfsr
(
    input               clk,
    input               rst_n,


    input [15:0]        lfsr_seed,
    input               lfsr_ld,


    input               lfsr_step,


    output reg [15:0]   lfsr_state_f,


    output reg          lfsr_out_f
);
localparam LFSR_WIDTH = 16;
localparam LFSR_FEEDBACK_TAPS = 16'b00000000000000000000000000000001;

always @(posedge clk or negedge rst_n)
begin
    if (!rst_n)
    begin
        lfsr_state_f <= 0;
    end
    else if (lfsr_ld)
    begin
        lfsr_state_f <= lfsr_seed;
    end
    else if (lfsr_step)
    begin
        lfsr_state_f <= {lfsr_state_f[15:1], lfsr_state_f[0] ^ lfsr_state_f[15] ^ lfsr_state_f[14] ^ lfsr_state_f[13] ^ lfsr_state_f[12] ^ lfsr_state_f[11] ^ lfsr_state_f[10] ^ lfsr_state_f[9] ^ lfsr_state_f[8] ^ lfsr_state_f[7] ^ lfsr_state_f[6] ^ lfsr_state_f[5] ^ lfsr_state_f[4] ^ lfsr_state_f[3] ^ lfsr_state_f[2] ^ lfsr_state_f[1] ^ LFSR_FEEDBACK_TAPS};
    end
end

assign lfsr_out_f = lfsr_state_f[15];

endmodule

module mux4_1n (
    input EN_n,
    input A, B,
    input D0, D1, D2, D3,
    output Y
);
reg Y_reg;
    always @(A, B, D0, D1, D2, D3) begin
        if (EN_n == 1'b0) begin
            Y_reg <= 1'b0;
        end else begin
            case ({A, B})
                2'b00: Y_reg <= D0;
                2'b01: Y_reg <= D1;
                2'b10: Y_reg <= D2;
                2'b11: Y_reg <= D3;
            endcase
        end
    end
    assign Y = Y_reg;
endmodule

