module FFlr(
input wire clk,
input wire [31:0] f,
output reg [31:0] g
); 

wire [31:0] len_raw;
wire [31:0] len;
wire [31:0] x_mask;
wire [31:0] incr;
wire [31:0] f_out;
wire [31:0] f_incr;
wire [31:0] f_masked;
wire [31:0] res;
  assign len_raw = f[30:23];
  assign len = len_raw - 255;
  assign x_mask = len[31:24] << 8;
  assign incr = x_mask >> 1;
  assign f_out = f[31:24] == 0 ? f[31:24] : f[31:24] + incr;
  assign f_incr = f[31:24] == 0 ? f[31:24] : f[31:24] + 1;
  assign f_masked = f[31:24] == 0 ? f[31:24] : f[31:24] << 1;
  assign res = f[31] == 1 ? {f[31:24],f[23:0]} : {f[31:24],f[23:0]} - 1;
  always @(posedge clk) begin
    g <= res;
  end
endmodule

