module echo_server_application_m_axis_read_package_reg_slice
#(parameter
    N = 8   
) (

    input  wire         clk,
    input  wire         reset,

    input  wire [N-1:0] s_data,
    input  wire         s_valid,
    output wire         s_ready,

    output wire [N-1:0] m_data,
    output wire         m_valid,
    input  wire         m_ready
);
localparam [1:0]
  ZERO = 2'b00,
  ONE  = 2'b01,
  TWO  = 2'b10;

reg  [N-1:0] data_p1;
reg  [N-1:0] data_p2;
reg  [1:0]   state;
reg  [1:0]   next;
reg  load_p1;
reg  load_p2;
reg  load_p1_from_p2;
wire         s_ready_t;

assign s_ready = s_ready_t;
assign m_data  = data_p1;
assign m_valid = load_p1;

assign s_ready_t = load_p1_from_p2 ? data_p2 : 1'b0;

always @(posedge clk) begin
  if (reset) begin
    data_p1 <= {N{1'b0}};
    data_p2 <= {N{1'b0}};
    state  <= ZERO;
    load_p1 <= 1'b0;
    load_p2 <= 1'b0;
    load_p1_from_p2 <= 1'b0;
  end else begin
    load_p1 <= 1'b0;
    load_p2 <= 1'b0;
    load_p1_from_p2 <= 1'b0;
    case (state)
    ZERO: begin
      if (s_valid & m_ready) begin
        data_p1 <= s_data;
        data_p2 <= s_data;
        load_p1 <= 1'b1;
        load_p2 <= 1'b1;
        load_p1_from_p2 <= 1'b1;
        next <= ONE;
      end
    end
    ONE: begin
      if (s_valid & m_ready) begin
        data_p1 <= s_data;
        data_p2 <= s_data;
        load_p1 <= 1'b1;
        load_p2 <= 1'b1;
        load_p1_from_p2 <= 1'b1;
        next <= TWO;
      end
    end
    TWO: begin
      if (s_valid & m_ready) begin
        data_p1 <= s_data;
        data_p2 <= s_data;
        load_p1 <= 1'b1;
        load_p2 <= 1'b1;
        load_p1_from_p2 <= 1'b1;
        next <= ZERO;
      end
    end
    default: next <= ZERO;
    endcase
    state <= next;
  end
end

endmodule

