	wire [MEM_WIDTH-1:0] addr;
	wire [WIDTH-1:0] jumpOffset;
	wire [WIDTH-1:0] signExtend;
	wire [WIDTH-1:0] PC;

	assign instr = instr_mem[addr];
	assign PC = addr;

	assign signExtend = jump ? {jumpOffset, {OFF_WIDTH{1'b0}}} : PC;

	assign addr = PC + 1;

	assign instr = instr_mem[signExtend];

	assign stall = jump;

	PC_reg #(WIDTH) pc_reg(clk, reset, PC, addr, stall);

endmodule

