module AND4X4 (IN1,IN2,IN3,IN4,Q);

output  Q;
input   IN1,IN2,IN3,IN4;
and (Q,IN1,IN2,IN3,IN4);

`ifdef functional
`else
specify
specparam in1_lh_q_lh=10,in1_hl_q_hl=10,in2_lh_q_lh=10,
in2_hl_q_hl=10,in3_lh_q_lh=10,in3_hl_q_hl=10,in4_lh_q_lh=10,
in4_hl_q_hl=10;
if ((IN1==1'b1))
(        IN2 +=> Q) = (in2_lh_q_lh,in2_hl_q_hl);
if ((IN1==1'b0))
(        IN2 -=> Q) = (in2_lh_q_lh,in2_hl_q_hl);
if ((IN2==1'b1))
(        IN1 +=> Q) = (in1_lh_q_lh,in1_hl_q_hl);
if ((IN2==1'b0))
(        IN1 -=> Q) = (in1_lh_q_lh,in1_hl_q_hl);
if ((IN3==1'b1))
(        IN1 +=> Q) = (in1_lh_q_lh,in1_hl_q_hl);
if ((IN3==1'b0))
(        IN1 -=> Q) = (in1_lh_q_lh,in1_hl_q_hl);
if ((IN4==1'b1))
(        IN1 +=> Q) = (in1_lh_q_lh,in1_hl_q_hl);
if ((IN4==1'b0))
(        IN1 -=> Q) = (in1_lh_q_lh,in1_hl_q_hl);
if ((IN4==1'b1))
(        IN2 +=> Q) = (in2_lh_q_lh,in2_hl_q_hl);
if ((IN4==1'b0))
(        IN2 -=> Q) = (in2_lh_q_lh,in2_hl_q_hl);
if ((IN3==1'b1))
(        IN2 +=> Q) = (in2_lh_q_lh,in2_hl_q_hl);
if ((IN3==1'b0))
(        IN2 -=> Q) = (in2_lh_q_lh,in2_hl_q_hl);
if ((IN3==1'b1))
(        IN4 +=> Q) = (in4_lh_q_lh,in4_hl_q_hl);
if ((IN3==1'b0))
(        IN4 -=> Q) = (in4_lh_q_lh,in4_hl_q_hl);
if ((IN4==1'b1))
(        IN3 +=> Q) = (in3_lh_q_lh,in3_hl_q_hl);
