module fsm_trafic_light(clk,reset, red,yellow, green);
input clk, reset;

output red,yellow,green;
reg red,yellow,green;
reg [2:0] state;
always @(posedge clk)
begin
	if (reset == 1)
	begin
		state <= 0;
		red <= 0;
		yellow <= 0;
		green <= 0;
	end
	else
	begin
		case (state)
			0: begin
				red <= 1;
				yellow <= 0;
				green <= 0;
				state <= 1;
			end
			1: begin
				red <= 0;
				yellow <= 1;
				green <= 0;
				state <= 2;
			end
			2: begin
				red <= 0;
				yellow <= 0;
				green <= 1;
				state <= 3;
			end
			3: begin
				red <= 0;
				yellow <= 1;
				green <= 0;
				state <= 0;
			end
		endcase
	end
end
endmodule

