module APB_master(input Transfer,              
                  input Wr_Rd,                 
                  input [4:0] Address,         
                  input [31:0] write_data,     
                  output reg [31:0] read_data, 
                  input PCLK,                  
                  input PRESETn,               
                  input PREADY,                
                  input [31:0] PRDATA,         
                  input PSLVERR,               
                  output reg [4:0] PADDR,      
                  output reg PSELx,            
                  output reg PENABLE,          
                  output reg PWRITE,           
                  output reg [31:0] PWDATA);
reg [1:0] state;
  always @(posedge PCLK) begin
    if (PRESETn == 0) begin
      state <= IDLE;
    end else begin
      case (state)
        IDLE: begin
          if (Transfer) begin
            if (Wr_Rd) begin
              PSELx <= 1;
              PADDR <= Address;
              PENABLE <= 1;
              PWRITE <= 1;
              PWDATA <= write_data;
              state <= SETUP;
            end else begin
              PSELx <= 0;
              PADDR <= Address;
              PENABLE <= 1;
              PWRITE <= 0;
              PWDATA <= write_data;
              state <= ACCESS;
            end
          end
        end
        SETUP: begin
          if (PREADY) begin
            PSELx <= 0;
            PADDR <= Address;
            PENABLE <= 1;
            PWRITE <= 0;
            PWDATA <= write_data;
            state <= ACCESS;
          end
        end
        ACCESS: begin
          if (PREADY) begin
            if (PSLVERR) begin
              PSELx <= 0;
              PADDR <= Address;
              PENABLE <= 1;
              PWRITE <= 0;
              PWDATA <= write_data;
              state <= IDLE;
            end else begin
              PSELx <= 0;
              PADDR <= Address;
              PENABLE <= 1;
              PWRITE <= 0;
              PWDATA <= write_data;
              state <= IDLE;
            end
          end
        end
        default: begin
          PSELx <= 0;
          PADDR <= Address;
          PENABLE <= 1;
          PWRITE <= 0;
          PWDATA <= write_data;
          state <= IDLE;
        end
      endcase
    end
  end
  always @(posedge PCLK) begin
    if (PRESETn == 0) begin
      read_data <= 0;
    end else begin
      case (state)
        IDLE: begin
          read_data <= 0;
        end
        SETUP: begin
          read_data <= PRDATA;
        end
        ACCESS: begin
          read_data <= PRDATA;
        end
        default: begin
          read_data <= 0;
        end
      endcase
    end
  end
endmodule

