module FIFO_toe_ackDelayFifoReadCount_V_V (
    clk,
    reset,
    if_empty_n,
    if_read_ce,
    if_read,
    if_dout,
    if_full_n,
    if_write_ce,
    if_write,
    if_din);

input clk;
input reset;
output if_empty_n;
input if_read_ce;
input if_read;
output[DATA_WIDTH - 1:0] if_dout;
output if_full_n;
input if_write_ce;
input if_write;
input[DATA_WIDTH - 1:0] if_din;
parameter MEM_STYLE = "shiftreg";
parameter DATA_WIDTH = 32'd1;
parameter ADDR_WIDTH = 32'd5;
parameter DEPTH = 32'd10;

wire[ADDR_WIDTH - 1:0] shiftReg_addr ;
wire[DATA_WIDTH - 1:0] shiftReg_data, shiftReg_q;
reg[ADDR_WIDTH:0] readAddress = {(ADDR_WIDTH+1){1'b1}};
reg readEnable = 0;
wire readEmpty_n = ~readEnable;
reg[ADDR_WIDTH:0] writeAddress = {ADDR_WIDTH{1'b0}};
reg writeEnable = 0;
wire writeFull_n = ~writeEnable;

assign if_empty_n = readEmpty_n;
assign if_full_n = writeFull_n;
assign if_dout = shiftReg_q;

always @(posedge clk) begin
    if (reset == 1'b1)
        readAddress <= {(ADDR_WIDTH+1){1'b1}};
    else if (if_read_ce == 1'b1)
        if (readEmpty_n == 1'b1)
            readAddress <= readAddress - 1;
end

always @(posedge clk) begin
    if (reset == 1'b1)
        writeAddress <= {ADDR_WIDTH{1'b0}};
    else if (if_write_ce == 1'b1)
        if (writeFull_n == 1'b1)
            writeAddress <= writeAddress + 1;
end

FIFO_toe_ackDelayFifoReadCount_V_V_shiftReg #(
    .DATA_WIDTH(DATA_WIDTH),
    .ADDR_WIDTH(ADDR_WIDTH),
    .DEPTH(DEPTH))
U_FIFO_toe_ackDelayFifoReadCount_V_V_shiftReg (
    .clk(clk),
    .data(if_din),
    .ce(writeEnable),
    .a(writeAddress[ADDR_WIDTH-1:0]),
    .q(shiftReg_data));

always @(posedge clk) begin
    if (reset == 1'b1)
        readEnable <= 0;
    else if (if_read == 1'b1 && readEmpty_n == 0)
        readEnable <= 1;
    else if (if_read == 1'b0 && readEnable == 1)
        readEnable <= 0;
end

always @(posedge clk) begin
    if (reset == 1'b1)
        writeEnable <= 0;
    else if (if_write == 1'b1 && writeFull_n == 0)
        writeEnable <= 1;
    else if (if_write == 1'b0 && writeEnable == 1)
        writeEnable <= 0;
end

assign shiftReg_addr = readAddress[ADDR_WIDTH:1];
assign shiftReg_data = if_din;

endmodule

