module KEY_MUX
(
	input PS2_CLK,
	input PS2_DAT,
	output [9:0]LEDR,
	output [6:0]HEX0,
	output [6:0]HEX1
);
wire [7:0]scan_code;
	assign scan_code = PS2_CLK ? PS2_DAT : 1'b0;

	assign LEDR = {S[3:0],NS[3:0]};
	assign HEX0 = in1;
	assign HEX1 = in2;

	assign in1 = scan_code[7:0];
	assign in2 = scan_code[15:8];
	assign in3 = scan_code[23:16];

	assign out = scan_code[31:24];

	reg [3:0]S,NS;
	reg [7:0]in1,in2,in3;
	reg [7:0]out;

	always @(posedge scan_code)
	begin
		S <= NS;
		NS <= 4'b0000;
		case (S)
			4'b0000: begin
				NS <= 4'b0001;
				in1 <= 8'b00000000;
				in2 <= 8'b00000000;
				in3 <= 8'b00000000;
			end
			4'b0001: begin
				NS <= 4'b0010;
				in1 <= in1;
				in2 <= in2;
				in3 <= in3;
			end
			4'b0010: begin
				NS <= 4'b0011;
				in1 <= in1;
				in2 <= in2;
				in3 <= in3;
			end
			4'b0011: begin
				NS <= 4'b0100;
				in1 <= in1;
				in2 <= in2;
				in3 <= in3;
			end
			4'b0100: begin
				NS <= 4'b0101;
				in1 <= in1;
				in2 <= in2;
				in3 <= in3;
			end
			4'b0101: begin
				NS <= 4'b0110;
				in1 <= in1;
				in2 <= in2;
				in3 <= in3;
			end
			4'b0110: begin
				NS <= 4'b0111;
				in1 <= in1;
				in2 <= in2;
				in3 <= in3;
			end
			4'b0111: begin
				NS <= 4'b1000;
				in1 <= in1;
				in2 <= in2;
				in3 <= in3;
			end
			4'b1000: begin
				NS <= 4'b1001;
				in1 <= in1;
				in2 <= in2;
				in3 <= in3;
			end
			4'b1001: begin
				NS <= 4'b1010;
				in1 <= in1;
				in2 <= in2;
				in3 <= in3;
			end
			4'b1010: begin
				NS <= 4'b1011;
				in1 <= in1;
				in2 <= in2;
				in3 <= in3;
			end
			4'b1011: begin
				NS <= 4'b1100;
				in1 <= in1;
				in2 <= in2;
				in3 <= in3;
			end
			4'b1100: begin
				NS <= 4'b1101;
				in1 <= in1;
				in2 <= in2;
				in3 <= in3;
			end
			4'b1101: begin
				NS <= 4'b1110;
				in1 <= in1;
				in2 <= in2;
				in3 <= in3;
			end
			4'b1110: begin
				NS <= 4'b1111;
				in1 <= in1;
				in2 <= in2;
				in3 <= in3;
			end
			4'b1111: begin
				NS <= 4'b0000;
				in1 <= out;
				in2 <= out;
				in3 <= out;
			end
		endcase
	end
endmodule

