reg aclr_reg;               
reg aclrout_reg;           

assign aclrout = aclrout_reg;

always @(posedge clk or negedge aclr) begin
    if (aclr == aclrval) begin
        aclr_reg <= aclrval;
        aclrout_reg <= aclroutval;
    end else begin
        aclr_reg <= aclr;
        aclrout_reg <= aclrout;
    end
end

always @(posedge clk) begin
    if (ena == 1'b1) begin
        if (stall == 1'b0) begin
            q_reg <= d;
        end
    end
end

assign q = q_reg;

