specparam
  width = 1,
  aclrval = 1'b0,
  aclroutval = 1'b0;

(posedge clk => (q +: q_reg)) = (0, 0);

if (aclr == aclrval) 
    (posedge aclr => (q +: q_reg)) = (0, 0);
else
    (negedge aclr => (q +: q_reg)) = (0, 0);

if (ena == 1'b1)
    (posedge clk => (q_reg +: d)) = (0, 0);

if (stall == 1'b1)
    (posedge clk => (q_reg +: d)) = (0, 0);

if (ena == 1'b1)
    (posedge clk => (q_reg +: aclr)) = (0, 0);

