module BaudTickGen(
	input clk, enable,
	output tick  
);
parameter ClkFrequency = 100000000;
	parameter Baud = 115200;
	parameter Oversampling = 1;
	
	wire [31:0] Acc;
	wire [31:0] Inc;
	
	assign Inc = (ClkFrequency / (Baud * Oversampling)) - 1;
	
	assign tick = (Acc == Inc);
	
	assign Acc = enable ? Acc + 1 : 0;
	
	assign log2 = $clog2(Inc);
	
endmodule

