module vga_sync_pulse
(
    input   i_clk,
    output  o_hsync,
    output  o_vsync,
    output reg [9:0] o_col_count = 0,
    output reg [9:0] o_row_count = 0
);
parameter COLUMNS = 1024;
    parameter ROWS = 768;
    parameter ACTIVE_COLUMNS = 640;
    parameter ACTIVE_ROWS = 480;
    always @(posedge i_clk)
    begin
        if (o_col_count == COLUMNS - 1)
        begin
            o_col_count <= 0;
            o_row_count <= o_row_count + 1;
        end
        else
            o_col_count <= o_col_count + 1;
    end
    always @(posedge i_clk)
    begin
        if (o_row_count == ROWS - 1)
            o_row_count <= 0;
        else
            o_row_count <= o_row_count + 1;
    end
    always @(posedge i_clk)
    begin
        if (o_col_count == 0)
            o_hsync <= 1;
        else
            o_hsync <= 0;
    end
    always @(posedge i_clk)
    begin
        if (o_row_count == 0)
            o_vsync <= 1;
        else
            o_vsync <= 0;
    end
endmodule

