module db (
        input clk, n_reset, button_in,
        output reg out
    );
parameter maxbit = 10;
    reg [maxbit-1:0] q_reg, q_next;
    reg q_add, q_reset;
    wire [maxbit-1:0] q_add, q_reset;
    wire button_in;
    reg f1, f2;
    always @(posedge clk or negedge n_reset) begin
        if (!n_reset) begin
            q_reg <= 0;
            f1 <= 0;
            f2 <= 0;
        end else begin
            q_reg <= q_next;
            f1 <= f2;
            f2 <= button_in;
        end
    end
    always @(posedge clk or negedge n_reset) begin
        if (!n_reset) begin
            q_add <= 0;
            q_reset <= 0;
        end else begin
            q_add <= f1 & ~f2;
            q_reset <= f1 & f2;
        end
    end
    always @(posedge clk or negedge n_reset) begin
        if (!n_reset) begin
            q_next <= 0;
        end else begin
            q_next <= q_reg + q_add;
            if (q_reset) begin
                q_next <= 0;
            end else if (q_reg == (2**maxbit-1)) begin
                q_next <= q_reg;
            end
        end
    end
    always @(posedge clk or negedge n_reset) begin
        if (!n_reset) begin
            out <= 0;
        end else begin
            out <= (q_reg == (2**maxbit-1)) & button_in;
        end
    end
endmodule

