module FIFO(
    input clock,
    input sclr,
    input rdreq, wrreq,
    output reg full, empty,
    input [7 : 0] data,
    output [7 : 0] q
);
reg [7 : 0] mem [15 : 0];
    reg [3 : 0] wp, rp;
    reg w_flag, r_flag;
    always @(posedge clock) begin
        if (sclr == 1'b1) begin
            wp <= 4'b0000;
            rp <= 4'b0000;
            w_flag <= 1'b0;
            r_flag <= 1'b0;
        end else begin
            if (wrreq == 1'b1) begin
                if (wp == 4'b1111) begin
                    wp <= 4'b0000;
                    w_flag <= 1'b1;
                end else begin
                    mem[wp] <= data;
                    wp <= wp + 1'b1;
                    w_flag <= 1'b0;
                end
            end
            if (rdreq == 1'b1) begin
                if (rp == 4'b1111) begin
                    rp <= 4'b0000;
                    r_flag <= 1'b1;
                end else begin
                    q <= mem[rp];
                    rp <= rp + 1'b1;
                    r_flag <= 1'b0;
                end
            end
        end
    end
    always @(posedge clock) begin
        if (sclr == 1'b1) begin
            full <= 1'b0;
            empty <= 1'b1;
        end else begin
            if (w_flag == 1'b1) begin
                full <= 1'b1;
                empty <= 1'b0;
            end else if (r_flag == 1'b1) begin
                full <= 1'b0;
                empty <= 1'b1;
            end else begin
                full <= 1'b0;
                empty <= 1'b0;
            end
        end
    end
endmodule

