module jk_flop (input J, K, clk,
                output reg Q, Qbar);
always @(posedge clk)
    if (J & K)
        Q <= ~Q;
    else if (J)
        Q <= 1;
    else if (K)
        Q <= 0;
    Qbar <= ~Q;
endmodule

module Walk2R_example (
	input logic vga_clk,
	input logic [9:0] DrawX, DrawY,
	input logic blank,
	output logic [3:0] red, green, blue
);
logic [13:0] rom_address;
logic [3:0] palette_red, palette_green, palette_blue;

logic [3:0] current_red, current_green, current_blue;

assign rom_address = (DrawX*14/640) + (DrawY*18/480 * 14/640);

assign {palette_red, palette_green, palette_blue} = rom[rom_address];

always_ff @ (posedge vga_clk) begin
	current_red <= palette_red;
	current_green <= palette_green;
	current_blue <= palette_blue;
end

assign red = blank ? current_red : 4'h0;
assign green = blank ? current_green : 4'h0;
assign blue = blank ? current_blue : 4'h0;

Walk2R_rom rom (
	.clock(vga_clk),
	.address(rom_address),
	.q(palette_red, palette_green, palette_blue)
);

Walk2R_palette palette (
	.index(palette_red),
	.q(red, green, blue)
);

endmodule

