input wire SEL,
output wire VAL,
output wire Z,
output wire [31:0] out_sqrt
); 

reg [31:0] x_0 = 1.0;
reg [31:0] x_i;
reg [31:0] x_i_mux;
reg [31:0] x_next;
reg [31:0] sqrt;
reg val_comb;
reg z_comb;
reg val_ff;
reg z_ff;
  always @(posedge CLK, posedge RST_n) begin
    if((RST_n == 1'b0)) begin
      x_0 <= 1.0;
      x_i <= 1.0;
      x_i_mux <= 1.0;
      x_next <= 1.0;
      sqrt <= 1.0;
      val_comb <= 1'b0;
      z_comb <= 1'b0;
      val_ff <= 1'b0;
      z_ff <= 1'b0;
    end else begin
      x_i <= x_i_mux;
      x_next <= (x_i + (n / x_i)) >> 1;
      if((n == 0)) begin
        sqrt <= 0;
        val_comb <= 1'b0;
        z_comb <= 1'b1;
        val_ff <= 1'b0;
        z_ff <= 1'b0;
      end else if((x_next >= x_i)) begin
        sqrt <= x_i;
        val_comb <= 1'b1;
        z_comb <= 1'b0;
        val_ff <= 1'b1;
        z_ff <= 1'b1;
      end else begin
        sqrt <= 1.0;
        val_comb <= 1'b0;
        z_comb <= 1'b0;
        val_ff <= 1'b0;
        z_ff <= 1'b0;
      end
      x_i_mux <= x_next;
    end
  end
  assign out_sqrt = out_sqrt_reg;
  assign out_sqrt_reg = sqrt;
  assign VAL = val_comb;
  assign Z = z_comb;
  always @(posedge CLK, posedge RST_n) begin
    if((RST_n == 1'b0)) begin
      val_ff <= 1'b0;
    end else begin
      if((EN == 1'b1)) begin
        val_ff <= val_comb;
      end
    end
  end
  always @(posedge CLK, posedge RST_n) begin
    if((RST_n == 1'b0)) begin
      z_ff <= 1'b0;
    end else begin
      if((EN == 1'b1)) begin
        z_ff <= z_comb;
      end
    end
  end
endmodule

