module cycloneii_latch(D, ENA, PRE, CLR, Q);

   input D;
   input ENA, PRE, CLR;
   output Q;
reg q_out = 1'b0;

   buf(D_in, D);
   buf(ENA_in, ENA);
   buf(PRE_in, PRE);
   buf(CLR_in, CLR);

   assign Q = q_out;

   always @(posedge D_in or posedge ENA_in or posedge PRE_in or posedge CLR_in) begin
      if (CLR_in == 1'b1) begin
         q_out <= 1'b0;
      end else if (PRE_in == 1'b1) begin
         q_out <= 1'b1;
      end else if (ENA_in == 1'b1) begin
         q_out <= D_in;
      end
   end

   specify
      specparam
         tplh$D$Q = 1.0,
         tphl$D$Q = 1.0,
         tplh$ENA$Q = 1.0,
         tphl$ENA$Q = 1.0,
         tplh$PRE$Q = 1.0,
         tphl$PRE$Q = 1.0,
         tplh$CLR$Q = 1.0,
         tphl$CLR$Q = 1.0;

      (D_in *> Q) = (tplh$D$Q, tphl$D$Q);
      (ENA_in *> Q) = (tplh$ENA$Q, tphl$ENA$Q);
      (PRE_in *> Q) = (tplh$PRE$Q, tphl$PRE$Q);
      (CLR_in *> Q) = (tplh$CLR$Q, tphl$CLR$Q);
   endspecify

endmodule

