                        (address + ADDR_RANGE3_OFFSET);

endmodule

module serial2parallel(
    input clk,
    input rst_n,
    input din_serial,
    input din_valid,
    output reg [7:0] dout_parallel,
    output reg dout_valid
);
reg [7:0] shift_reg;
    reg [3:0] count;
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            shift_reg <= 8'b0;
            count <= 4'b0;
            dout_valid <= 1'b0;
        end else begin
            if (din_valid) begin
                shift_reg <= {shift_reg[6:0], din_serial};
                count <= count + 1'b1;
                if (count == 8'b1111) begin
                    dout_valid <= 1'b1;
                    dout_parallel <= shift_reg;
                end else begin
                    dout_valid <= 1'b0;
                end
            end else begin
                dout_valid <= 1'b0;
            end
        end
    end
endmodule

