		output wire       dk);
wire [3:0] d1, d2, d3;
	wire       dk1, dk2, dk3;
	wire       drot;

	assign drot = d[3];

	assign d1 = drot;
	assign d2 = d1;
	assign d3 = d2;

	assign dk1 = dk;
	assign dk2 = dk1;
	assign dk3 = dk2;

	assign d = d3;
	assign dk = dk3;

	stage #(.DELAY(9)) s1 (init, d1, dk1);
	stage #(.DELAY(9)) s2 (init, d2, dk2);
	stage #(.DELAY(9)) s3 (init, d3, dk3);

endmodule

