module serial(clk, reset, rxD,sout,signal,counter);
input clk;      
input reset;    
input rxD;   

output reg [n-1:0]sout; 
output reg signal;   
output reg [31:0]counter;
parameter n = 30;
parameter count = 4;

reg [2:0]delay;

top t(clk, reset, rxD, s_in, counter, signal);

always @(posedge clk)
begin
    if (reset == 1'b1)
    begin
        counter <= 0;
        signal <= 0;
    end
    else
    begin
        if (counter == count)
        begin
            signal <= 1;
            delay <= 3'b111;
        end
        else
        begin
            signal <= 0;
            delay <= 3'b000;
        end
        if (delay == 3'b111)
        begin
            counter <= counter + 1;
            delay <= 3'b000;
        end
        else
        begin
            counter <= counter;
            delay <= delay + 1;
        end
    end
end

assign sout = s_in;
endmodule

