module Bin2BCDConverter_4
#(
	parameter INPUT_BIT_WIDTH  = 8
)
(
    input [(INPUT_BIT_WIDTH-1):0] Input,
    output reg [3:0] Digit3,
    output reg [3:0] Digit2,
    output reg [3:0] Digit1,
    output reg [3:0] Digit0
);
always @(Input)
begin
    for (integer i = 0; i < INPUT_BIT_WIDTH; i = i + 1)
    begin
        if (Digit3 > 9)
            Digit3 = Digit3 + 3;
        if (Digit2 > 9)
            Digit2 = Digit2 + 3;
        if (Digit1 > 9)
            Digit1 = Digit1 + 3;
        if (Digit0 > 9)
            Digit0 = Digit0 + 3;
        Digit3 = Digit3 << 1;
        Digit2 = Digit2 << 1;
        Digit1 = Digit1 << 1;
        Digit0 = Digit0 << 1;
        Digit3[0] = Input[i];
    end
end
endmodule

