module NBitCounterChain #(
   parameter counterSize   = 16,
   parameter numOfCounters = 3054
) (
   input  wire                   clk,
   input  wire                   reset,
   output wire [counterSize-1:0] outCount
);
reg [counterSize-1:0] counts [numOfCounters-1:0];
   reg [numOfCounters-1:0] terminalCounts [numOfCounters-1:0];
   generate
      genvar i;
      for (i = 0; i < numOfCounters; i = i + 1) begin
         reg enable;
         assign enable = (i == 0) ? 1'b1 : terminalCounts[i-1];
         NBitCounter #(
            .counterSize(counterSize)
         ) counter (
            .clk(clk),
            .reset(reset),
            .enable(enable),
            .count(counts[i]),
            .outCount(counts[i])
         );
         assign terminalCounts[i] = counts[i] == (2**counterSize-1) ? 1'b1 : 1'b0;
      end
   endgenerate
   assign outCount = counts[numOfCounters-1];
endmodule

