module vga_sync(
input wire clk,
input wire rst,
output reg active,
output reg hsync,
output reg vsync,
output wire [9:0] xaddr,
output wire [9:0] yaddr
); 

parameter [31:0] hsize = 1024;
parameter [31:0] vsize = 768;
parameter [31:0] hfront = 16;
parameter [31:0] hback = 16;
parameter [31:0] vfront = 10;
parameter [31:0] vback = 10;
reg [31:0] h_count_reg;
reg [31:0] v_count_reg;
  always @(posedge clk) begin
    if(rst == 1'b1) begin
      h_count_reg <= 0;
      v_count_reg <= 0;
    end else begin
      h_count_reg <= h_count_reg + 1;
      v_count_reg <= v_count_reg + 1;
    end
  end
  assign xaddr = h_count_reg;
  assign yaddr = v_count_reg;
  always @(posedge clk) begin
    if(rst == 1'b1) begin
      active <= 1'b0;
      hsync <= 1'b0;
      vsync <= 1'b0;
    end else begin
      if((h_count_reg > (hsize - hback - hfront)) && (h_count_reg < (hsize - hback)) && (v_count_reg > (vsize - vback - vfront)) && (v_count_reg < (vsize - vback))) begin
        active <= 1'b1;
      end
      else begin
        active <= 1'b0;
      end
      if((h_count_reg > (hsize - hback - hfront)) && (h_count_reg < (hsize - hback)) && (v_count_reg > (vsize - vback - vfront)) && (v_count_reg < (vsize - vback))) begin
        hsync <= 1'b1;
      end
      else begin
        hsync <= 1'b0;
      end
      if((h_count_reg > (hsize - hback - hfront)) && (h_count_reg < (hsize - hback)) && (v_count_reg > (vsize - vback - vfront)) && (v_count_reg < (vsize - vback))) begin
        vsync <= 1'b1;
      end
      else begin
        vsync <= 1'b0;
      end
    end
  end
endmodule

