module TopModule (
    clk,
    areset,
    train_valid,
    train_taken,
    state
);
input clk;
input areset;
input train_valid;
input train_taken;
output reg [1:0] state;
always @(posedge clk) begin
    if (arst) begin
        state <= 2'b01;
    end else if (train_valid) begin
        if (train_taken) begin
            if (state == 2'b11) begin
                state <= 2'b00;
            end else begin
                state <= state + 1;
            end
        end else begin
            if (state == 2'b00) begin
                state <= 2'b11;
            end else begin
                state <= state - 1;
            end
        end
    end
end
endmodule

