module TopModule(
    clk,
    reset,
    data,
    count,
    counting,
    done,
    ack
);
input  clk;
input  reset;
input  data;
output reg [3:0] count;
output reg counting;
output reg done;
input  ack;
always @(posedge clk) begin
    if (reset) begin
        count <= 4'd0;
        counting <= 1'b0;
        done <= 1'b0;
    end else begin
        if (counting) begin
            if (count == 4'd0) begin
                done <= 1'b1;
                counting <= 1'b0;
            end else begin
                count <= count - 1;
            end
        end else begin
            if (data == 1'b1 && data[1] == 1'b1 && data[0] == 1'b0 && data[3] == 1'b1) begin
                count <= 4'd0;
                counting <= 1'b1;
            end
        end
    end
end
endmodule

