  input [3:0] state,
  output reg [3:0] next_state,
  output out
);
always @(state, in) begin
    case (state)
      4'b0001: begin
        next_state = 4'b0001;
        out = 1'b0;
      end
      4'b0010: begin
        next_state = 4'b0010;
        out = 1'b0;
      end
      4'b0100: begin
        next_state = 4'b0100;
        out = 1'b0;
      end
      4'b1000: begin
        next_state = 4'b1000;
        out = 1'b1;
      end
    endcase
  end
endmodule

module TopModule (
  input clk,
  input load,
  input [9:0] data,
  output tc
);
reg [9:0] count;
  reg tc;
  always @(posedge clk) begin
    if (load) begin
      count <= data;
      tc <= 0;
    end else begin
      if (count == 0) begin
        tc <= 1;
      end else begin
        count <= count - 1;
        tc <= 0;
      end
    end
  end
endmodule

module TopModule (
  input clk,
  input enable,
  input S,
  input A,
  input B,
  input C,
  output reg Z
);
reg [7:0] Q;
  always @(posedge clk) begin
    if (enable) begin
      Q[0] <= S;
      Q[1] <= Q[0];
      Q[2] <= Q[1];
      Q[3] <= Q[2];
      Q[4] <= Q[3];
      Q[5] <= Q[4];
      Q[6] <= Q[5];
      Q[7] <= Q[6];
    end
  end
  always @(A or B or C or Q) begin
    if (A == 0 && B == 0 && C == 0) Z <= Q[0];
    else if (A == 0 && B == 0 && C == 1) Z <= Q[1];
    else if (A == 0 && B == 1 && C == 0) Z <= Q[2];
    else if (A == 0 && B == 1 && C == 1) Z <= Q[3];
    else if (A == 1 && B == 0 && C == 0) Z <= Q[4];
    else if (A == 1 && B == 0 && C == 1) Z <= Q[5];
    else if (A == 1 && B == 1 && C == 0) Z <= Q[6];
    else if (A == 1 && B == 1 && C == 1) Z <= Q[7];
  end
endmodule

module TopModule (
  input clk,
  input reset,
  output reg [4:0] q
);
always @(posedge clk) begin
    if (reset) begin
      q <= 1;
    end else begin
      q[4] <= q[3] ^ q[0];
      q[3] <= q[2] ^ q[0];
      q[2] <= q[1] ^ q[0];
      q[1] <= q[0];
    end
  end
endmodule

module TopModule (
  input a,
  input b,
  output out_and,
  output out_or,
  output out_xor,
  output out_nand,
  output out_nor,
  output out_xnor,
  output out_anotb
);
assign out_and = a & b;
  assign out_or = a | b;
  assign out_xor = a ^ b;
  assign out_nand = ~a & b;
  assign out_nor = ~a | ~b;
  assign out_xnor = ~a ^ b;
  assign out_anotb = a & ~b;
endmodule

