module TopModule (
  input [5:0] y,
  input w,
  output Y1,
  output Y3
);
reg [5:0] y;
  assign Y1 = y[1];
  assign Y3 = y[3];
  always @(y or w) begin
    case (y[5:0])
      6'b000001: y <= 6'b000010;
      6'b000010: y <= 6'b000100;
      6'b000100: y <= 6'b001000;
      6'b001000: y <= 6'b010000;
      6'b010000: y <= 6'b100000;
      6'b100000: y <= 6'b000001;
    endcase
  end
endmodule

module TopModule (
  input  [99:0] in,
  output [99:0] out_both,
  output [99:0] out_any,
  output [99:0] out_different
);
assign out_both[99] = 0;
  assign out_any[99] = 0;
  assign out_different[99] = 0;
  genvar i;
  generate
    for (i = 0; i < 99; i = i + 1) begin
      assign out_both[i] = in[i] & in[i+1];
      assign out_any[i] = in[i] | in[i+1];
      assign out_different[i] = in[i] ^ in[i+1];
    end
  endgenerate
endmodule

