  always @(posedge clk) begin
    if (reset) begin
      shift_ena <= 1'b1;
    end else begin
      if (shift_ena) begin
        shift_ena <= 1'b0;
      end else begin
        shift_ena <= 1'b1;
      end
    end
  end
endmodule

module TopModule (
  input clk,
  input reset,
  input data,
  output start_shifting
);
reg [3:0] state;
  reg [3:0] next_state;
  reg start_shifting;
  always @(posedge clk) begin
    if (reset) begin
      state <= 0;
      start_shifting <= 0;
    end else begin
      state <= next_state;
      start_shifting <= next_state == 4'b1101 ? 1 : 0;
    end
  end
  always @(state, data) begin
    next_state = state;
    case (state)
      0: begin
        if (data) begin
          next_state = 1;
        end
      end
      1: begin
        if (data) begin
          next_state = 2;
        end
      end
      2: begin
        if (data) begin
          next_state = 3;
        end
      end
      3: begin
        if (data) begin
          next_state = 4;
        end
      end
      4: begin
        if (data) begin
          next_state = 4;
        end
        else begin
          next_state = 0;
        end
      end
      default: begin
        next_state = 0;
      end
    endcase
  end
endmodule

