    case (scancode[15:0])
      16'he06b: left <= 1'b1;
      16'he072: down <= 1'b1;
      16'he074: right <= 1'b1;
      16'he075: up <= 1'b1;
      default: left <= 1'b0;
    endcase
  end
endmodule

module TopModule (
  input clk,
  input in,
  input reset,
  output out
);
reg out;
  reg state;
  always @(posedge clk) begin
    if (reset) begin
      state <= B;
      out <= 1;
    end else begin
      case (state)
        B: begin
          if (in) begin
            state <= A;
            out <= 1;
          end else begin
            state <= B;
            out <= 1;
          end
        end
        A: begin
          if (in) begin
            state <= B;
            out <= 0;
          end else begin
            state <= A;
            out <= 0;
          end
        end
      endcase
    end
  end
endmodule

module TopModule (
  input clk,
  input in,
  input areset,
  output out
);
reg out;
  reg B;
  reg A;
  always @(posedge clk or posedge areset) begin
    if (arst) begin
      B <= 1'b1;
      A <= 1'b0;
    end else begin
      B <= A;
      A <= in;
    end
  end
  assign out = B;
endmodule

module TopModule (
  input clk,
  input j,
  input k,
  input reset,
  output out
);
reg out;
  always @(posedge clk) begin
    if (reset) begin
      out <= 0;
    end else if (j) begin
      if (out) begin
        out <= 1;
      end else begin
        out <= 0;
      end
    end else begin
      if (k) begin
        out <= 1;
      end else begin
        out <= 0;
      end
    end
  end
endmodule

module TopModule (
  input [3:0] in,
  output reg [1:0] pos
);
always @* begin
    if (in == 4'b0) begin
      pos = 2'b0;
    end else begin
      pos = 2'b0;
      for (int i = 0; i < 4; i++) begin
        if (in[i] == 1'b1) begin
          pos = i;
          break;
        end
      end
    end
  end
endmodule

