module TopModule (
  input clk,
  input in,
  input areset,
  output out
);
reg [1:0] state;
  reg out;
  always @(posedge clk) begin
    if (arst) begin
      state <= 2'b00;
      out <= 1'b0;
    end else begin
      case (state)
        2'b00: begin
          if (in == 1'b0) begin
            state <= 2'b01;
            out <= 1'b0;
          end else begin
            state <= 2'b00;
            out <= 1'b0;
          end
        end
        2'b01: begin
          if (in == 1'b0) begin
            state <= 2'b10;
            out <= 1'b0;
          end else begin
            state <= 2'b01;
            out <= 1'b0;
          end
        end
        2'b10: begin
          if (in == 1'b0) begin
            state <= 2'b11;
            out <= 1'b0;
          end else begin
            state <= 2'b10;
            out <= 1'b0;
          end
        end
        2'b11: begin
          if (in == 1'b0) begin
            state <= 2'b11;
            out <= 1'b0;
          end else begin
            state <= 2'b00;
            out <= 1'b1;
          end
        end
      endcase
    end
  end
endmodule

