module TopModule (
  input clk,
  input reset,
  input x,
  output reg z
);
reg [2:0] y;
  always @(posedge clk) begin
    if (reset) begin
      y <= 3'b000;
    end else begin
      case (y)
        3'b000: begin
          if (x == 1'b0) begin
            y <= 3'b000;
          end else begin
            y <= 3'b001;
          end
        end
        3'b001: begin
          if (x == 1'b0) begin
            y <= 3'b001;
          end else begin
            y <= 3'b100;
          end
        end
        3'b010: begin
