module TopModule (
  input clk,
  input [7:0] in,
  input reset,
  output done
);
reg [1:0] state;
  reg [2:0] count;
  reg done_reg;
  always @(posedge clk) begin
    if (reset) begin
      state <= 2'b00;
      count <= 3'b000;
      done_reg <= 1'b0;
    end else begin
      case (state)
        2'b00: begin
          if (in[3]) begin
            state <= 2'b01;
            count <= 3'b000;
            done_reg <= 1'b0;
          end
        end
        2'b01: begin
          if (in[3]) begin
            state <= 2'b10;
            count <= 3'b000;
          end
        end
        2'b10: begin
          if (in[3]) begin
            state <= 2'b11;
            count <= 3'b000;
          end
        end
        2'b11: begin
          if (in[3]) begin
            state <= 2'b00;
            count <= 3'b000;
            done_reg <= 1'b0;
          end else begin
            count <= count + 1'b1;
            if (count == 3'b111) begin
              state <= 2'b00;
              done_reg <= 1'b1;
            end
          end
        end
        default: begin
          state <= 2'b00;
          count <= 3'b000;
          done_reg <= 1'b0;
        end
      endcase
    end
  end
  assign done = done_reg;
endmodule

module TopModule (
  input clk,
  input aresetn,
  input x,
  output reg z
);
localparam [1:0] S0 = 2'b00;
  localparam [1:0] S1 = 2'b01;
  localparam [1:0] S2 = 2'b10;
  localparam [1:0] S3 = 2'b11;
  reg [1:0] current_state;
  reg [1:0] next_state;
  always @(posedge clk or negedge aresetn) begin
    if (arstn == 1'b0) begin
      current_state <= S0;
    end else begin
      current_state <= next_state;
    end
  end
  always @(current_state, x) begin
    case (current_state)
      S0: begin
        if (x == 1'b1) begin
          next_state <= S1;
        end else begin
          next_state <= S0;
        end
      end
      S1: begin
        if (x == 1'b0) begin
          next_state <= S2;
        end else begin
          next_state <= S0;
        end
      end
      S2: begin
        if (x == 1'b1) begin
          next_state <= S3;
        end else begin
          next_state <= S0;
        end
      end
      S3: begin
        if (x == 1'b0) begin
          next_state <= S2;
        end else begin
          next_state <= S0;
        end
      end
      default: next_state <= S0;
    endcase
  end
  always @(current_state) begin
    case (current_state)
      S0, S1, S2, S3: z <= 1'b0;
    endcase
  end
endmodule

