module TopModule (
  input clk,
  input resetn,
  input  [2:0] r,
  output [2:0] g
);
reg [2:0] state;
  reg [2:0] next_state;
  always @(posedge clk or negedge resetn) begin
    if (!resetn) begin
      state <= 3'b000;
    end else begin
      state <= next_state;
    end
  end
  always @(*) begin
    case (state)
      3'b000: begin
        if (r[0] == 1'b1) begin
          next_state = 3'b001;
        end else if (r[1] == 1'b1) begin
          next_state = 3'b010;
        end else if (r[2] == 1'b1) begin
          next_state = 3'b011;
        end else begin
          next_state = 3'b000;
        end
      end
      3'b001: begin
        next_state = 3'b001;
      end
      3'b010: begin
        next_state = 3'b010;
      end
      3'b011: begin
        next_state = 3'b011;
      end
      default: begin
        next_state = 3'b000;
      end
    endcase
  end
  assign g[0] = (state == 3'b000) ? 1'b0 : 1'b1;
  assign g[1] = (state == 3'b000) ? 1'b0 : 1'b1;
  assign g[2] = (state == 3'b000) ? 1'b0 : 1'b1;
endmodule

module TopModule (
  input clk,
