    if (reset) begin
      fr2 <= 1'b0;
      fr1 <= 1'b0;
      fr0 <= 1'b0;
      dfr <= 1'b0;
      last_s <= 3'b000;
    end else begin
      if (s[2] > last_s[2]) begin
        fr2 <= 1'b0;
        fr1 <= 1'b0;
        fr0 <= 1'b0;
        dfr <= 1'b0;
      end else if (s[2] < last_s[2]) begin
        fr2 <= 1'b1;
        fr1 <= 1'b1;
        fr0 <= 1'b1;
        dfr <= 1'b0;
      end else begin
